/**
 * Dynamic agent roster builder — audit W1.3+W3.3 (N-1 ghost entry, N-2 stale
 * deepseek model labels, N-3 profile drift).
 *
 * Source of truth = the real Hermes profile directories on disk plus each
 * profile's config.yaml (ONLY model.default + model.provider are read — the
 * api_key line is never parsed or printed). Persona/name/group come from the
 * static PROFILE_META map carried over from the old hardcoded ROSTER in
 * `src/app/api/agents/route.ts`; profiles without a map entry fall back to
 * the canonical controller list (controller-roster.json, regenerated by cron
 * INV-7) or group "general".
 *
 * Results are cached in memory (TTL 60s). If the scan fails entirely the last
 * successful snapshot is served (never a 500); if no scan ever succeeded a
 * static-safe snapshot derived from PROFILE_META is used.
 */
import { existsSync, readFileSync, readdirSync } from "fs";
import { dirname, join } from "path";

export interface RosterAgent {
  id: string;
  profile: string;
  name: string;
  emoji: string;
  role: string;
  model: string;
  level: number;
  group: string;
}

// Hermes profile root on this machine (override with HERMES_PROFILES_DIR).
const PROFILES_DIR =
  process.env.HERMES_PROFILES_DIR || "C:/Users/TRIAL/AppData/Local/hermes/profiles";

// Canonical controller lane roster (policy 31-08-2026, refreshed by cron INV-7).
