/**
 * Extract "<provider>/<default>" from a profile config.yaml. Line scanner on
 * purpose: no YAML dependency, and only the two whitelisted keys inside the
 * top-level `model:` block are ever looked at (api_key/base_url untouched).
 */
export function parseModelLabel(yamlText: string): string {
  let inModel = false;
  let def = "";
  let prov = "";
  for (const line of yamlText.split(/\r?\n/)) {
    if (/^model:\s*$/.test(line)) {
      inModel = true;
      continue;
    }
    if (!inModel) continue;
    const m = line.match(/^ {2}(default|provider):\s*(\S.*?)\s*$/);
    if (m) {
      const val = m[2].replace(/^["']|["']$/g, "");
      if (m[1] === "default") def = val;
      else prov = val;
      continue;
    }
    if (/^\S/.test(line)) break; // dedent: left the model: block
  }
  if (!def && !prov) return "unknown";
  if (prov && def) return `${prov}/${def}`;
  return def || prov;
}

function controllerSet(): Set<string> {
  try {
    const j = JSON.parse(readFileSync(CONTROLLER_ROSTER_FILE, "utf8"));
    if (Array.isArray(j.controllers) && j.controllers.length > 0) {
      return new Set<string>(j.controllers.filter((c: unknown) => typeof c === "string"));
    }
  } catch {
    /* fall through to embedded list */
  }
  return new Set<string>(CONTROLLER_FALLBACK);
}

/**
 * Build the roster from disk reality: every folder under PROFILES_DIR is one
 * agent (name = folder name), plus the Hermes root profile ("default",
 * surfaced to the dashboard as id "brahma" like the old static roster).
 * Throws when the directory cannot be read or yields nothing — callers decide
 * the fallback.
 */
export function buildRoster(profilesDir: string = PROFILES_DIR): RosterAgent[] {
  const controllers = controllerSet();
  const dirs = readdirSync(profilesDir, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .sort();
  const profiles = ["default", ...dirs.filter((d) => d !== "default")];

  const out: RosterAgent[] = [];
  for (const profile of profiles) {
    const cfgPath =
      profile === "default"
        ? join(dirname(profilesDir), "config.yaml")
        : join(profilesDir, profile, "config.yaml");
    let model = "unknown";
    try {
      if (existsSync(cfgPath)) model = parseModelLabel(readFileSync(cfgPath, "utf8"));
    } catch {
      /* unreadable config keeps model=unknown, agent still listed */
    }
    const meta = PROFILE_META[profile];
    if (meta) {
      out.push({
        id: profile === "default" ? "brahma" : profile,
        profile,
        model,
        name: meta.name,
        emoji: meta.emoji,
        role: meta.role,
        level: meta.level,
        group: meta.group,
      });
    } else {
      const isController = controllers.has(profile);
      out.push({
        id: profile,
        profile,
        name: profile,
        emoji: "\u{1F916}",
        role: isController ? "Controller \u00b7 Roster kanonis" : "Profil Hermes \u00b7 dinamis",
        model,
        level: 3,
        group: isController ? "controller" : "general",
      });
    }
  }

  if (out.length === 0) throw new Error(`no profile directories found under ${profilesDir}`);
  out.sort((a, b) => a.level - b.level || a.profile.localeCompare(b.profile));
  return out;
}

// ── In-memory cache with static-safe fallback ───────────────────────────────
const TTL_MS = 60_000;
let cache: { at: number; roster: RosterAgent[] } | null = null;

/** Last-known-good roster; never throws, never returns an empty list. */
export function getRoster(): RosterAgent[] {
  const now = Date.now();
  if (cache && now - cache.at < TTL_MS) return cache.roster;
  try {
    const roster = buildRoster();
    cache = { at: now, roster };
    return roster;
  } catch (e) {
    console.error("[agent-roster] disk scan failed, serving fallback:", (e as Error).message);
    if (cache) {
      cache = { at: now, roster: cache.roster }; // keep serving last good snapshot
      return cache.roster;
    }
    // Never had a successful scan: static-safe snapshot from the persona map.
    const fallback: RosterAgent[] = Object.entries(PROFILE_META).map(([profile, meta]) => ({
      id: profile === "default" ? "brahma" : profile,
      profile,
      model: "unknown",
      name: meta.name,
      emoji: meta.emoji,
      role: meta.role,
      level: meta.level,
      group: meta.group,
    }));
    fallback.sort((a, b) => a.level - b.level || a.profile.localeCompare(b.profile));
    return fallback;
  }
}
